// Parse the AI response - handle both 'text' and 'output' keys
const raw = $input.first().json.text || $input.first().json.output || '';

// Strip markdown fences if present
const cleaned = raw
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch(e) {
  throw new Error('Failed to parse AI response: ' + cleaned);
}

return [{
  json: {
    customer_id:               parsed.customer_id        || 'Unknown',
    full_name:                 parsed.full_name          || 'Unknown',
    current_plan:              parsed.current_plan       || 'Unknown',
    active_addons:             parsed.active_addons      || 'None',
    question:                  parsed.question           || '',
    answer:                    parsed.answer             || '',
    recommended_bundle:        parsed.recommended_bundle || 'None',
    bundle_cost:               parsed.bundle_cost        || 'N/A',
    upgrade_savings:           parsed.upgrade_savings    || 'N/A',
    eligibility:               parsed.eligibility        || 'N/A',
    is_lead:                   parsed.is_lead === true ? 'Yes' : 'No',
    lead_reason:               parsed.lead_reason        || '',
    next_action:               parsed.next_action        || 'No Action Required',
    confidence:                parseFloat(parsed.confidence) || 0.0,
    confidence_reason:         parsed.confidence_reason  || '',
    logged_at:                 new Date().toISOString()
  }
}];

const body = $input.first().json.body || $input.first().json;

return [{
  json: {
    'Customer ID':                    body.customer_id        || body['Customer ID']                     || 'Unknown',
    'Full Name':                      body.full_name          || body['Full Name']                       || 'Unknown',
    'Choose your Telecom plan':       body.current_plan       || body['Choose your Telecom plan']        || 'Basic',
    'Choose your data roaming add-ons:': body.active_addons   || body['Choose your data roaming add-ons:'] || 'None',
    'Ask your question:':             body.question           || body['Ask your question:']              || ''
  }
}];
